import{_ as a,o as t,c as r,am as i}from"./chunks/framework.Brvj4i6c.js";const p=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),n={name:"glossaire.md"};function o(s,e,l,u,d,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="accessibilite-aa-wcag" tabindex="-1">Accessibilité AA (WCAG) <a class="header-anchor" href="#accessibilite-aa-wcag" aria-label="Permalink to &quot;Accessibilité AA (WCAG)&quot;">​</a></h3><p>Niveau de règles qui rend un écran utilisable par tous, y compris avec un lecteur d&#39;écran ou au clavier : contraste, libellés, ordre de lecture. Les WCAG sont les règles internationales de référence.</p><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><p>Point d&#39;entrée par lequel un logiciel en interroge un autre pour échanger des données. Sa disponibilité dit si ce service répond.</p><h3 id="arbitrage" tabindex="-1">Arbitrage <a class="header-anchor" href="#arbitrage" aria-label="Permalink to &quot;Arbitrage&quot;">​</a></h3><p>Décision entre plusieurs options qui ne tiennent pas toutes dans la capacité disponible.</p><h3 id="assistant" tabindex="-1">Assistant <a class="header-anchor" href="#assistant" aria-label="Permalink to &quot;Assistant&quot;">​</a></h3><p>Le produit qu&#39;on utilise au quotidien (ChatGPT, Copilot, Claude.ai, Gemini) : une interface posée sur un harness, autour d&#39;un modèle.</p><h3 id="avoir" tabindex="-1">Avoir <a class="header-anchor" href="#avoir" aria-label="Permalink to &quot;Avoir&quot;">​</a></h3><p>Document comptable qui annule ou corrige une facture déjà émise : une facture émise ne se modifie pas.</p><h3 id="business-case" tabindex="-1">Business case <a class="header-anchor" href="#business-case" aria-label="Permalink to &quot;Business case&quot;">​</a></h3><p>Dossier qui compare les options d&#39;une initiative : coûts, bénéfices attendus, risques, hypothèses et inconnues.</p><h3 id="capacite" tabindex="-1">Capacité <a class="header-anchor" href="#capacite" aria-label="Permalink to &quot;Capacité&quot;">​</a></h3><p>Quantité de travail que l&#39;équipe peut prendre dans un sprint donné, compte tenu des absences.</p><h3 id="cas-limite" tabindex="-1">Cas limite <a class="header-anchor" href="#cas-limite" aria-label="Permalink to &quot;Cas limite&quot;">​</a></h3><p>Situation inhabituelle où la règle ne s&#39;applique pas comme d&#39;habitude : paiement refusé, demande annulée, article indisponible…</p><h3 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h3><p>Question de contrôle à la fin d&#39;un exercice. Ta réponse reste dans ce navigateur.</p><h3 id="cmdb" tabindex="-1">CMDB <a class="header-anchor" href="#cmdb" aria-label="Permalink to &quot;CMDB&quot;">​</a></h3><p>Base qui recense les applications et composants du système d&#39;information, leurs propriétaires et leurs dépendances (par exemple dans ServiceNow).</p><h3 id="connecteur" tabindex="-1">Connecteur <a class="header-anchor" href="#connecteur" aria-label="Permalink to &quot;Connecteur&quot;">​</a></h3><p>Logiciel qui relie deux systèmes pour qu&#39;ils échangent des données : le connecteur PMS relie Lanterne au système de gestion de l&#39;hôtel. Un outil d&#39;IA peut aussi avoir des connecteurs vers Jira, GitLab ou ServiceNow : ils ne s&#39;utilisent que s&#39;ils sont autorisés.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="contre-signal" tabindex="-1">Contre-signal <a class="header-anchor" href="#contre-signal" aria-label="Permalink to &quot;Contre-signal&quot;">​</a></h3><p>Donnée qui va contre l&#39;idée qu&#39;on défend (des clients qui préfèrent un contact humain, par exemple). On la garde et on la montre.</p><h3 id="critere-d-acceptation" tabindex="-1">Critère d&#39;acceptation <a class="header-anchor" href="#critere-d-acceptation" aria-label="Permalink to &quot;Critère d&#39;acceptation&quot;">​</a></h3><p>Condition vérifiable qu&#39;une user story doit remplir, souvent écrite « Étant donné…, quand…, alors… ».</p><h3 id="derive-de-contexte" tabindex="-1">Dérive de contexte <a class="header-anchor" href="#derive-de-contexte" aria-label="Permalink to &quot;Dérive de contexte&quot;">​</a></h3><p>Session qui se dégrade quand la context window se remplit d&#39;ajouts, de corrections et d&#39;informations périmées ou contradictoires : elle reste crédible mais s&#39;éloigne du besoin initial.</p><h3 id="design-system" tabindex="-1">Design system <a class="header-anchor" href="#design-system" aria-label="Permalink to &quot;Design system&quot;">​</a></h3><p>Bibliothèque partagée de composants d&#39;écran et de règles d&#39;usage (ici, Lueur). On n&#39;utilise que ses composants ; un besoin qu&#39;elle ne couvre pas se signale.</p><h3 id="discovery-decouverte" tabindex="-1">Discovery (découverte) <a class="header-anchor" href="#discovery-decouverte" aria-label="Permalink to &quot;Discovery (découverte)&quot;">​</a></h3><p>Travail pour comprendre les besoins des clients (retours, entretiens, données) avant de choisir quoi construire.</p><h3 id="dod-definition-of-done" tabindex="-1">DoD (Definition of Done) <a class="header-anchor" href="#dod-definition-of-done" aria-label="Permalink to &quot;DoD (Definition of Done)&quot;">​</a></h3><p>Liste de critères qu&#39;un travail doit remplir pour être considéré comme terminé.</p><h3 id="dor-definition-of-ready" tabindex="-1">DoR (Definition of Ready) <a class="header-anchor" href="#dor-definition-of-ready" aria-label="Permalink to &quot;DoR (Definition of Ready)&quot;">​</a></h3><p>Liste de critères qu&#39;un besoin ou une user story doit remplir pour être pris en développement.</p><h3 id="epopee" tabindex="-1">Épopée <a class="header-anchor" href="#epopee" aria-label="Permalink to &quot;Épopée&quot;">​</a></h3><p>Grand ensemble de travail découpé en plusieurs user stories (« epic » dans Jira).</p><h3 id="fuite-de-donnees" tabindex="-1">Fuite de données <a class="header-anchor" href="#fuite-de-donnees" aria-label="Permalink to &quot;Fuite de données&quot;">​</a></h3><p>Données confidentielles envoyées à un assistant non maîtrisé (version grand public).</p><h3 id="garde-fou" tabindex="-1">Garde-fou <a class="header-anchor" href="#garde-fou" aria-label="Permalink to &quot;Garde-fou&quot;">​</a></h3><p>Indicateur surveillé pour vérifier qu&#39;un progrès ne se fait pas au détriment d&#39;autre chose.</p><h3 id="grounding" tabindex="-1">Grounding <a class="header-anchor" href="#grounding" aria-label="Permalink to &quot;Grounding&quot;">​</a></h3><p>Ancrer la réponse dans des sources vérifiables plutôt que dans la « mémoire » du modèle.</p><h3 id="hallucination" tabindex="-1">Hallucination <a class="header-anchor" href="#hallucination" aria-label="Permalink to &quot;Hallucination&quot;">​</a></h3><p>Réponse fausse mais présentée avec assurance et vraisemblance.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA avant qu&#39;elle soit utilisée.</p><h3 id="instructions-personnalisees-assistant-personnalise" tabindex="-1">Instructions personnalisées / assistant personnalisé <a class="header-anchor" href="#instructions-personnalisees-assistant-personnalise" aria-label="Permalink to &quot;Instructions personnalisées / assistant personnalisé&quot;">​</a></h3><p>Consignes enregistrées une fois et réappliquées : toujours (instructions personnalisées) ou dans un espace dédié (GPT, Projet Claude, agent Copilot).</p><h3 id="kpi" tabindex="-1">KPI <a class="header-anchor" href="#kpi" aria-label="Permalink to &quot;KPI&quot;">​</a></h3><p>Indicateur de suivi d&#39;une activité (volume, délai, taux). Tous les KPI ne sont pas des résultats clés.</p><h3 id="kr-resultat-cle" tabindex="-1">KR (résultat clé) <a class="header-anchor" href="#kr-resultat-cle" aria-label="Permalink to &quot;KR (résultat clé)&quot;">​</a></h3><p>Résultat mesurable qui dit si un objectif est atteint. Il mesure un effet, pas un livrable.</p><h3 id="mcp-model-context-protocol" tabindex="-1">MCP (Model Context Protocol) <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP (Model Context Protocol)&quot;">​</a></h3><p>Standard pour brancher de nouveaux tools sur un assistant : applications et données de l&#39;entreprise.</p><h3 id="merge-request-mr-ou-pull-request" tabindex="-1">Merge request (MR) ou pull request <a class="header-anchor" href="#merge-request-mr-ou-pull-request" aria-label="Permalink to &quot;Merge request (MR) ou pull request&quot;">​</a></h3><p>Demande d&#39;intégrer une modification au code du produit. Fusionnée : la modification est intégrée ; brouillon : rien n&#39;est encore livré.</p><h3 id="okr" tabindex="-1">OKR <a class="header-anchor" href="#okr" aria-label="Permalink to &quot;OKR&quot;">​</a></h3><p>Objectifs et résultats clés : un objectif qualitatif, et deux à quatre résultats clés mesurables.</p><h3 id="pms" tabindex="-1">PMS <a class="header-anchor" href="#pms" aria-label="Permalink to &quot;PMS&quot;">​</a></h3><p>Système de gestion de l&#39;hôtel : réservations, état des chambres, note du client.</p><h3 id="portefeuille" tabindex="-1">Portefeuille <a class="header-anchor" href="#portefeuille" aria-label="Permalink to &quot;Portefeuille&quot;">​</a></h3><p>Ensemble des produits d&#39;un même domaine, dont les priorités et les moyens sont arbitrés ensemble (ici, le portefeuille Séjour).</p><h3 id="pre-autorisation" tabindex="-1">Pré-autorisation <a class="header-anchor" href="#pre-autorisation" aria-label="Permalink to &quot;Pré-autorisation&quot;">​</a></h3><p>Montant réservé sur la carte du client à son arrivée, encaissé au moment de régler la note.</p><h3 id="preproduction" tabindex="-1">Préproduction <a class="header-anchor" href="#preproduction" aria-label="Permalink to &quot;Préproduction&quot;">​</a></h3><p>Environnement qui reproduit la production pour tester avant la mise en service ; les vrais clients n&#39;y ont pas accès.</p><h3 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h3><p>La demande envoyée au modèle, consignes comprises.</p><h3 id="recette" tabindex="-1">Recette <a class="header-anchor" href="#recette" aria-label="Permalink to &quot;Recette&quot;">​</a></h3><p>Vérification, avant la mise en service, que ce qui a été développé respecte les critères d&#39;acceptation. L&#39;environnement de recette sert à ces essais.</p><h3 id="roadmap-feuille-de-route" tabindex="-1">Roadmap (feuille de route) <a class="header-anchor" href="#roadmap-feuille-de-route" aria-label="Permalink to &quot;Roadmap (feuille de route)&quot;">​</a></h3><p>Ce que l&#39;équipe prévoit de faire maintenant, ensuite et plus tard, et pourquoi.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h3><p>Savoir-faire emballé (consignes, modèles, exemples, parfois des scripts) que l&#39;assistant charge <strong>à la demande</strong>, quand la tâche correspond. Plus léger que des instructions permanentes, partageable dans une équipe. Claude parle d&#39;« Agent Skills » ; d&#39;autres assistants ont des équivalents.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (tool calling).</p><h3 id="transcription" tabindex="-1">Transcription <a class="header-anchor" href="#transcription" aria-label="Permalink to &quot;Transcription&quot;">​</a></h3><p>Texte produit automatiquement à partir de l&#39;enregistrement d&#39;une réunion. Elle peut contenir des trous et des erreurs.</p><h3 id="user-story" tabindex="-1">User story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User story&quot;">​</a></h3><p>Description courte d&#39;un besoin du point de vue de l&#39;utilisateur : « En tant que…, je veux…, afin de… ».</p><h3 id="velocite" tabindex="-1">Vélocité <a class="header-anchor" href="#velocite" aria-label="Permalink to &quot;Vélocité&quot;">​</a></h3><p>Quantité de travail, en points, que l&#39;équipe termine en moyenne par sprint.</p><h2 id="termes-du-design" tabindex="-1">Termes du design <a class="header-anchor" href="#termes-du-design" aria-label="Permalink to &quot;Termes du design&quot;">​</a></h2><h3 id="charte-editoriale" tabindex="-1">Charte éditoriale <a class="header-anchor" href="#charte-editoriale" aria-label="Permalink to &quot;Charte éditoriale&quot;">​</a></h3><p>Règles de ton, de vocabulaire et de longueur des textes d&#39;un produit.</p><h3 id="chemin-d-erreur" tabindex="-1">Chemin d&#39;erreur <a class="header-anchor" href="#chemin-d-erreur" aria-label="Permalink to &quot;Chemin d&#39;erreur&quot;">​</a></h3><p>Suite d&#39;écrans ou de messages quand quelque chose ne se passe pas comme prévu.</p><h3 id="cible-tactile" tabindex="-1">Cible tactile <a class="header-anchor" href="#cible-tactile" aria-label="Permalink to &quot;Cible tactile&quot;">​</a></h3><p>Zone de l&#39;écran qui réagit au toucher ; Lueur demande 44 px au moins.</p><h3 id="critere-de-reussite" tabindex="-1">Critère de réussite <a class="header-anchor" href="#critere-de-reussite" aria-label="Permalink to &quot;Critère de réussite&quot;">​</a></h3><p>Ce que l&#39;on observe pour dire qu&#39;une tâche de test est réussie, fixé avant la séance.</p><h3 id="criteres-de-recrutement" tabindex="-1">Critères de recrutement <a class="header-anchor" href="#criteres-de-recrutement" aria-label="Permalink to &quot;Critères de recrutement&quot;">​</a></h3><p>Règles qui décident quels clients on interroge : segments, hôtels, séjours écartés.</p><h3 id="demande-d-evolution" tabindex="-1">Demande d&#39;évolution <a class="header-anchor" href="#demande-d-evolution" aria-label="Permalink to &quot;Demande d&#39;évolution&quot;">​</a></h3><p>Besoin qu&#39;aucun composant du design system ne couvre, signalé à son responsable avec un argument d&#39;usage.</p><h3 id="direction-de-design" tabindex="-1">Direction de design <a class="header-anchor" href="#direction-de-design" aria-label="Permalink to &quot;Direction de design&quot;">​</a></h3><p>Manière d&#39;ordonner un flow : nombre d&#39;écrans, ordre, place de l&#39;action qui engage.</p><h3 id="etat-d-un-ecran-ou-d-un-composant" tabindex="-1">État (d&#39;un écran ou d&#39;un composant) <a class="header-anchor" href="#etat-d-un-ecran-ou-d-un-composant" aria-label="Permalink to &quot;État (d&#39;un écran ou d&#39;un composant)&quot;">​</a></h3><p>Situation à prévoir en plus du cas normal : chargement, vide, erreur, succès ; chacune a son texte.</p><h3 id="etat-vide" tabindex="-1">État vide <a class="header-anchor" href="#etat-vide" aria-label="Permalink to &quot;État vide&quot;">​</a></h3><p>Écran ou liste sans contenu, avec un texte qui explique pourquoi et quoi faire.</p><h3 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h3><p>Enchaînement des écrans et des choix d&#39;un client pour accomplir une tâche.</p><h3 id="gravite-d-un-probleme" tabindex="-1">Gravité (d&#39;un problème) <a class="header-anchor" href="#gravite-d-un-probleme" aria-label="Permalink to &quot;Gravité (d&#39;un problème)&quot;">​</a></h3><p>Priorité d&#39;un problème de test, déduite du nombre de participants touchés et de l&#39;impact.</p><h3 id="guide-d-entretien" tabindex="-1">Guide d&#39;entretien <a class="header-anchor" href="#guide-d-entretien" aria-label="Permalink to &quot;Guide d&#39;entretien&quot;">​</a></h3><p>Trame chronométrée d&#39;un entretien (introduction, questions, relances, conclusion), préparée à l&#39;avance.</p><h3 id="handoff" tabindex="-1">Handoff <a class="header-anchor" href="#handoff" aria-label="Permalink to &quot;Handoff&quot;">​</a></h3><p>Transmission du design aux développeurs, avec tout ce qu&#39;il faut pour le construire.</p><h3 id="hypothese" tabindex="-1">Hypothèse <a class="header-anchor" href="#hypothese" aria-label="Permalink to &quot;Hypothèse&quot;">​</a></h3><p>Énoncé qu&#39;une recherche peut confirmer ou infirmer ; si elle contient déjà sa réponse, c&#39;est une conclusion déguisée.</p><h3 id="ideation" tabindex="-1">Idéation <a class="header-anchor" href="#ideation" aria-label="Permalink to &quot;Idéation&quot;">​</a></h3><p>Phase où l&#39;on produit beaucoup d&#39;idées avant de trier.</p><h3 id="insight" tabindex="-1">Insight <a class="header-anchor" href="#insight" aria-label="Permalink to &quot;Insight&quot;">​</a></h3><p>Enseignement porté par plusieurs entretiens, qui change une décision de design.</p><h3 id="irritant" tabindex="-1">Irritant <a class="header-anchor" href="#irritant" aria-label="Permalink to &quot;Irritant&quot;">​</a></h3><p>Ce qui gêne le client dans son parcours.</p><h3 id="journey-map" tabindex="-1">Journey map <a class="header-anchor" href="#journey-map" aria-label="Permalink to &quot;Journey map&quot;">​</a></h3><p>Tableau du parcours d&#39;un client, étape par étape (actions, émotions, irritants), où chaque émotion cite sa preuve.</p><h3 id="lecteur-d-ecran" tabindex="-1">Lecteur d&#39;écran <a class="header-anchor" href="#lecteur-d-ecran" aria-label="Permalink to &quot;Lecteur d&#39;écran&quot;">​</a></h3><p>Logiciel qui lit l&#39;interface à voix haute (VoiceOver, NVDA…).</p><h3 id="libelle" tabindex="-1">Libellé <a class="header-anchor" href="#libelle" aria-label="Permalink to &quot;Libellé&quot;">​</a></h3><p>Texte court d&#39;un bouton, d&#39;un champ ou d&#39;un titre.</p><h3 id="nom-accessible" tabindex="-1">Nom accessible <a class="header-anchor" href="#nom-accessible" aria-label="Permalink to &quot;Nom accessible&quot;">​</a></h3><p>Nom d&#39;un composant tel que l&#39;expose la technologie d&#39;assistance.</p><h3 id="ordre-de-focus" tabindex="-1">Ordre de focus <a class="header-anchor" href="#ordre-de-focus" aria-label="Permalink to &quot;Ordre de focus&quot;">​</a></h3><p>Ordre dans lequel le clavier passe d&#39;un élément à l&#39;autre.</p><h3 id="parcours-cible" tabindex="-1">Parcours cible <a class="header-anchor" href="#parcours-cible" aria-label="Permalink to &quot;Parcours cible&quot;">​</a></h3><p>Le parcours que l&#39;on vise après la conception, par opposition au parcours actuel.</p><h3 id="persona" tabindex="-1">Persona <a class="header-anchor" href="#persona" aria-label="Permalink to &quot;Persona&quot;">​</a></h3><p>Portrait-type d&#39;un groupe de clients, construit à partir de sources (entretiens, données), jamais inventé.</p><h3 id="placeholder" tabindex="-1">Placeholder <a class="header-anchor" href="#placeholder" aria-label="Permalink to &quot;Placeholder&quot;">​</a></h3><p>Texte indicatif dans un champ, qui disparaît à la saisie ; il ne remplace pas un libellé.</p><h3 id="question-orientee" tabindex="-1">Question orientée <a class="header-anchor" href="#question-orientee" aria-label="Permalink to &quot;Question orientée&quot;">​</a></h3><p>Question qui suggère la réponse attendue (« seriez-vous intéressé par… », « c&#39;est rassurant, n&#39;est-ce pas ? »).</p><h3 id="question-ouverte" tabindex="-1">Question ouverte <a class="header-anchor" href="#question-ouverte" aria-label="Permalink to &quot;Question ouverte&quot;">​</a></h3><p>Question qui invite à raconter (« racontez-moi la dernière fois… ») et ne se règle pas par oui ou non.</p><h3 id="ratio-de-contraste" tabindex="-1">Ratio de contraste <a class="header-anchor" href="#ratio-de-contraste" aria-label="Permalink to &quot;Ratio de contraste&quot;">​</a></h3><p>Rapport de luminance entre un texte et son fond : 4,5:1 au moins pour le texte courant au niveau AA.</p><h3 id="scenario-de-test" tabindex="-1">Scénario de test <a class="header-anchor" href="#scenario-de-test" aria-label="Permalink to &quot;Scénario de test&quot;">​</a></h3><p>Situation réaliste donnée au participant pour qu&#39;il agisse, sans nommer les boutons ni donner la réponse.</p><h3 id="signal-isole" tabindex="-1">Signal isolé <a class="header-anchor" href="#signal-isole" aria-label="Permalink to &quot;Signal isolé&quot;">​</a></h3><p>Remarque d&#39;un seul client ou participant, gardée de côté et à confirmer, sans en faire un insight.</p><h3 id="spec-de-handoff" tabindex="-1">Spec de handoff <a class="header-anchor" href="#spec-de-handoff" aria-label="Permalink to &quot;Spec de handoff&quot;">​</a></h3><p>Document par écran qui décrit composants, états, textes, comportements, erreurs et accessibilité pour les développeurs.</p><h3 id="texte-alternatif" tabindex="-1">Texte alternatif <a class="header-anchor" href="#texte-alternatif" aria-label="Permalink to &quot;Texte alternatif&quot;">​</a></h3><p>Description textuelle d&#39;une image, lue par le lecteur d&#39;écran ; vide si l&#39;image est décorative.</p><h3 id="ux-writing" tabindex="-1">UX writing <a class="header-anchor" href="#ux-writing" aria-label="Permalink to &quot;UX writing&quot;">​</a></h3><p>Écrire les textes de l&#39;interface (libellés, messages, états) avec un ton et des règles tenus.</p><h3 id="verbatim" tabindex="-1">Verbatim <a class="header-anchor" href="#verbatim" aria-label="Permalink to &quot;Verbatim&quot;">​</a></h3><p>Phrase exacte prononcée par un client, citée mot pour mot avec son repère (C1…).</p><h3 id="wireframe" tabindex="-1">Wireframe <a class="header-anchor" href="#wireframe" aria-label="Permalink to &quot;Wireframe&quot;">​</a></h3><p>Description simple d&#39;un écran (composants, contenus, actions) sans mise en forme graphique.</p>',164)])])}const m=a(n,[["render",o]]);export{p as __pageData,m as default};
